import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    if n < 2:
        return 'C'

    my_last, opp_last = history[-1]
    my_prev, opp_prev = history[-2]

    # Detect early defection and retaliate once.
    if opp_last == 'D':
        if opp_prev == 'C' and my_prev == 'C' and my_last == 'C':
            return 'D'
        if my_last == 'D' and opp_last == 'D':
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent seems cooperative, stay cooperative but occasionally probe.
    opp_defections = sum(1 for a, b in history if b == 'D')
    my_defections = sum(1 for a, b in history if a == 'D')

    if opp_defections == 0:
        if n >= 8 and n % 13 == 0 and my_defections < 2:
            return 'D'
        return 'C'

    cooperation_ratio = (n - opp_defections) / float(n)

    if cooperation_ratio > 0.8:
        if n % 17 == 0:
            return 'D'
        return 'C'

    if cooperation_ratio > 0.5:
        if my_last == 'D':
            return 'C'
        if opp_last == 'D':
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'

    # Low cooperation: defect mostly, but occasionally forgive to avoid deadlock.
    if my_last == 'D':
        return 'D'
    if rng.random() < 0.2:
        return 'C'
    return 'D'

